needle='''        snapshot_existing(now, f"BEFORE_TAKER:{side}", decision_id)\n        max_price = min(0.99, float(price) + 0.02)'''
block='''        # R4 research-only Maker-first handoff: before a structural Repair Taker, give an existing\n        # weak-side passive carrier one terminal-safe 1T refresh + bounded progress window.\n        # This does not create new responsibility quantity; it reuses only the genuine remaining carrier.\n        mf_mode=str(maker_first_repair_mode).upper()\n        if mf_mode in {"REPRICE_1T"}:\n            pre_mf=c.inventory.features(int(now)); net_mf=float(pre_mf.get("combined_net") or 0.0)\n            structural_mf=bool((side=="DOWN" and net_mf>EPS) or (side=="UP" and net_mf<-EPS))\n            if structural_mf:\n                ev={"atMs":int(now),"side":side,"mode":mf_mode,"waitMs":int(maker_first_wait_ms),"preGap":abs(net_mf),"result":"NO_CARRIER"}\n                bf0=mod.outcome_book(a.book,None) or {}; bid0=bf0.get("up_bid") if side=="UP" else bf0.get("down_bid")\n                cand=[]\n                for key,o in list(c.orders.items()):\n                    if o.side!=side: continue\n                    sp=a.snap(key); st=str(sp.get("status") or "")\n                    rem=float(sp.get("leavesQty") or 0.0) if st in {"NEW","PARTIALLY_FILLED"} else 0.0\n                    if rem<=EPS: continue\n                    off=((float(bid0)-float(o.price))/mod.GRID) if bid0 is not None else math.nan\n                    cand.append((off,int(now)-int(o.placed_at_ms),key,o,sp,rem))\n                if cand:\n                    off,age,key,o,sp,rem0=max(cand,key=lambda z:((z[0] if math.isfinite(z[0]) else -1e9),z[1]))\n                    ev.update({"oldOrderId":o.id,"oldPrice":float(o.price),"oldOffsetTicks":float(off),"oldAgeMs":int(age),"remainingAtDecision":float(rem0)})\n                    # A young carrier already received a full progress window; do not churn it.\n                    if age < int(maker_first_wait_ms):\n                        ev["result"]="YOUNG_CARRIER_CONTINUE"; maker_first_handoff_events.append(ev); return False\n                    # If the carrier is already at/inside the target 1T zone and still stalled, passive reachability\n                    # has already been tested. Hand off to Taker rather than resetting queue priority.\n                    if math.isfinite(off) and off <= 1.5:\n                        ev["result"]="NEAR_TOUCH_HANDOFF_TAKER"; maker_first_handoff_events.append(ev)\n                    else:\n                        cum0=float(sp.get("cumExecQty") or 0.0); before_fill_n=len(maker_fill_events)\n                        a.cancel(key); cancel_at=int(now)+int(entry_latency_ms)+int(response_latency_ms); a.advance(market_id,cancel_at); fill_wrap(snapshot,cancel_at)\n                        sp2=a.snap(key); st2=str(sp2.get("status") or ""); cum2=float(sp2.get("cumExecQty") or 0.0); during=max(0.0,cum2-cum0); rem=max(0.0,rem0-during)\n                        ev.update({"cancelTerminalMs":cancel_at,"cancelStatus":st2,"fillDuringCancelShares":during,"genuineRemainingQty":rem})\n                        if st2 in {"CANCELED","FILLED","REJECTED","EXPIRED"} and rem>EPS:\n                            qr=c._quote(side,1)\n                            if qr is not None:\n                                tick,px=qr\n                                while (side,tick) in c.orders:\n                                    tick-=1\n                                    if tick<int(round(mod.MIN_PRICE/mod.GRID)): break\n                                    px=round(tick*mod.GRID,2)\n                                if tick>=int(round(mod.MIN_PRICE/mod.GRID)) and (side,tick) not in c.orders:\n                                    native_side="bids" if side=="UP" else "asks"; native_price=round(px if side=="UP" else 1.0-px,10); initial=float(a.book.get(native_side,{}).get(native_price,0.0))\n                                    c.sequence+=1; oid=f"R4_MAKER_FIRST:{market_id}:{side}:{tick}:{cancel_at}:{c.sequence}"\n                                    no=mod.PaperOrder(oid,side,int(tick),float(px),float(rem),cancel_at,cancel_at*1000000,initial,native_side,native_price,False); nk=(side,int(tick)); c.orders[nk]=no; num,rc=a.submit(nk,no)\n                                    if rc==0:\n                                        c.placements.append({"at_ms":cancel_at,"side":side,"price":float(px),"reason":"R4_MAKER_FIRST_REPRICE_1T","p":0.0,"occupied_before":0}); c.current_metrics["makerPlacements"]+=1; c.run_metrics["makerPlacements"]+=1\n                                        target=int(cancel_at)+int(maker_first_wait_ms); a.advance(market_id,target); fill_wrap(snapshot,target)\n                                        progress=sum(float(x.get("deltaShares") or 0.0) for x in maker_fill_events[before_fill_n:] if str(x.get("side"))==side and int(x.get("atMs") or 0)>=cancel_at)\n                                        post=c.inventory.features(target); postnet=float(post.get("combined_net") or 0.0); still=bool((side=="DOWN" and postnet>EPS) or (side=="UP" and postnet<-EPS))\n                                        ev.update({"result":"PROGRESS_CONTINUE" if progress>EPS else ("RESOLVED_CONTINUE" if not still else "NO_PROGRESS_HANDOFF_TAKER"),"newOrderId":oid,"newPrice":float(px),"newQty":float(rem),"progressShares":float(progress),"postGap":abs(postnet),"progressWindowEndMs":target})\n                                        maker_first_handoff_events.append(ev)\n                                        if progress>EPS or not still: return False\n                                        # Handoff occurs at the end of the bounded Maker progress window using current public ask.\n                                        now=target; bf1=mod.outcome_book(a.book,None) or {}; fresh=bf1.get("up_ask") if side=="UP" else bf1.get("down_ask")\n                                        if fresh is not None and math.isfinite(float(fresh)): price=float(fresh)\n                                    else:\n                                        c.orders.pop(nk,None); ev.update({"result":"REPRICE_REJECT_HANDOFF_TAKER","submitRc":int(rc)}); maker_first_handoff_events.append(ev)\n                                else:\n                                    ev["result"]="REPRICE_OCCUPIED_HANDOFF_TAKER"; maker_first_handoff_events.append(ev)\n                            else:\n                                ev["result"]="NO_VALID_REQUOTE_HANDOFF_TAKER"; maker_first_handoff_events.append(ev)\n                        elif rem<=EPS:\n                            ev["result"]="RESOLVED_DURING_CANCEL"; maker_first_handoff_events.append(ev); return False\n                        else:\n                            ev["result"]="CANCEL_NOT_TERMINAL_HANDOFF_TAKER"; maker_first_handoff_events.append(ev)\n                else:\n                    maker_first_handoff_events.append(ev)\n        snapshot_existing(now, f"BEFORE_TAKER:{side}", decision_id)\n        max_price = min(0.99, float(price) + 0.02)'''
